SELECT jsonb_build_object(
'version',version(),'database',current_database(),'currentUser',current_user,
'schemas',(SELECT jsonb_agg(nspname ORDER BY nspname) FROM pg_namespace WHERE nspname NOT LIKE 'pg_%' AND nspname<>'information_schema'),
'tables',(SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'forceRls',c.relforcerowsecurity) ORDER BY n.nspname,c.relname),'[]') FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','clinical','clinical_service','dentaia_admin') AND c.relkind='r'),
'columns',(SELECT coalesce(jsonb_agg(jsonb_build_object('table_schema',table_schema,'table_name',table_name,'column_name',column_name,'ordinal_position',ordinal_position,'data_type',data_type,'udt_schema',udt_schema,'udt_name',udt_name,'is_nullable',is_nullable,'column_default',column_default) ORDER BY table_schema,table_name,ordinal_position),'[]') FROM information_schema.columns WHERE table_schema IN ('public','clinical','clinical_service','dentaia_admin')),
'constraints',(SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',con.conname,'type',con.contype,'definition',pg_get_constraintdef(con.oid,true),'validated',con.convalidated) ORDER BY n.nspname,c.relname,con.conname),'[]') FROM pg_constraint con JOIN pg_class c ON c.oid=con.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','clinical','clinical_service','dentaia_admin')),
'indexes',(SELECT coalesce(jsonb_agg(to_jsonb(i) ORDER BY schemaname,tablename,indexname),'[]') FROM pg_indexes i WHERE schemaname IN ('public','clinical','clinical_service','dentaia_admin')),
'policies',(SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY schemaname,tablename,policyname),'[]') FROM pg_policies p WHERE schemaname IN ('public','clinical','dentaia_admin','storage')),
'functions',(SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'result',pg_get_function_result(p.oid),'owner',pg_get_userbyid(p.proowner),'securityDefiner',p.prosecdef,'config',p.proconfig,'acl',p.proacl,'definition',pg_get_functiondef(p.oid)) ORDER BY n.nspname,p.proname,p.oid),'[]') FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('public','clinical','clinical_service','dentaia_admin') AND p.prokind='f'),
'roles',(SELECT jsonb_agg(jsonb_build_object('name',rolname,'superuser',rolsuper,'login',rolcanlogin,'bypassRls',rolbypassrls,'createRole',rolcreaterole,'inherit',rolinherit) ORDER BY rolname) FROM pg_roles WHERE rolname IN ('postgres','anon','authenticated','authenticator','service_role','supabase_auth_admin','supabase_storage_admin','dentaia_clinical_executor')),
'roleMemberships',(SELECT coalesce(jsonb_agg(jsonb_build_object('role',r.rolname,'member',m.rolname,'admin',a.admin_option) ORDER BY r.rolname,m.rolname),'[]') FROM pg_auth_members a JOIN pg_roles r ON r.oid=a.roleid JOIN pg_roles m ON m.oid=a.member WHERE r.rolname LIKE 'dentaia%' OR m.rolname LIKE 'dentaia%'),
'buckets',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'private',NOT public,'fileSizeLimit',file_size_limit,'allowedMimeTypes',allowed_mime_types) ORDER BY id),'[]') FROM storage.buckets),
'authSummary',(SELECT jsonb_build_object('users',count(*),'confirmed',count(*) FILTER(WHERE email_confirmed_at IS NOT NULL),'anonymous',count(*) FILTER(WHERE is_anonymous),'banned',count(*) FILTER(WHERE banned_until>now())) FROM auth.users),
'mfaSummary',(SELECT jsonb_build_object('verified',count(*) FILTER(WHERE status='verified'),'unverified',count(*) FILTER(WHERE status='unverified')) FROM auth.mfa_factors),
'counts',jsonb_build_object('profiles',(SELECT count(*) FROM public.profiles),'dentists',(SELECT count(*) FROM public.dentists),'requests',(SELECT count(*) FROM public.appointment_requests),'consents',(SELECT count(*) FROM public.patient_consents),'photos',(SELECT count(*) FROM public.dental_photos),'storageObjects',(SELECT count(*) FROM storage.objects)),
'postgresAuthPrivileges',jsonb_build_object('selectUsers',has_table_privilege('postgres','auth.users','SELECT'),'updateUsers',has_table_privilege('postgres','auth.users','UPDATE'),'selectSessions',has_table_privilege('postgres','auth.sessions','SELECT'),'selectMfa',has_table_privilege('postgres','auth.mfa_factors','SELECT')),
'triggers',(SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',t.tgname,'definition',pg_get_triggerdef(t.oid,true)) ORDER BY n.nspname,c.relname,t.tgname),'[]') FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE NOT t.tgisinternal AND n.nspname IN ('public','clinical','clinical_service','dentaia_admin'))
) AS catalog;
